create table if not exists public.cchan_relationships (user_id text primary key,familiarity integer not null default 0,trust integer not null default 0,affection integer not null default 0,comfort integer not null default 0,tension integer not null default 0,interaction_count integer not null default 0,last_interaction_at timestamptz,updated_at timestamptz not null default now());
create table if not exists public.cchan_memories (id bigint generated by default as identity primary key,user_id text not null,memory_type text not null default 'fact',summary text not null,confidence numeric not null default 0.7,importance numeric not null default 0.5,last_seen_at timestamptz not null default now(),created_at timestamptz not null default now());
create index if not exists cchan_memories_user_idx on public.cchan_memories(user_id,importance desc,last_seen_at desc);
